window.ScripturaLexicons.BDAG_PART_0125 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entrope-bdag\" data-source=\"BDAG\" data-search=\"ἐντροπή, ῆς, ἡ entropḗ substantivo feminino vergonha; humilhação; respeito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐντροπή, ῆς, ἡ</td><td>substantivo feminino</td><td>vergonha; humilhação; respeito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entryphao-bdag\" data-source=\"BDAG\" data-search=\"ἐντρυφάω entrypháō verbo deleitar-se; entregar-se a excessos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐντρυφάω</td><td>verbo</td><td>deleitar-se; entregar-se a excessos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entynchano-bdag\" data-source=\"BDAG\" data-search=\"ἐντυγχάνω entynchánō verbo recorrer; interceder; orar; ler BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐντυγχάνω</td><td>verbo</td><td>recorrer; interceder; orar; ler</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entylisso-bdag\" data-source=\"BDAG\" data-search=\"ἐντυλίσσω entylíssō verbo envolver; enrolar; dobrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐντυλίσσω</td><td>verbo</td><td>envolver; enrolar; dobrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entypoo-bdag\" data-source=\"BDAG\" data-search=\"ἐντυπόω entypóō verbo; voz passiva atestada gravar; entalhar; imprimir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐντυπόω</td><td>verbo; voz passiva atestada</td><td>gravar; entalhar; imprimir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enybrizo-bdag\" data-source=\"BDAG\" data-search=\"ἐνυβρίζω enybrízō verbo insultar; ultrajar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνυβρίζω</td><td>verbo</td><td>insultar; ultrajar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enydros-bdag\" data-source=\"BDAG\" data-search=\"ἔνυδρος, ον énydros adjetivo que vive na água BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔνυδρος, ον</td><td>adjetivo</td><td>que vive na água</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enypniazomai-bdag\" data-source=\"BDAG\" data-search=\"ἐνυπνιάζομαι enypniázomai verbo; depoente sonhar; ter visões em sonhos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνυπνιάζομαι</td><td>verbo; depoente</td><td>sonhar; ter visões em sonhos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enypnion-bdag\" data-source=\"BDAG\" data-search=\"ἐνύπνιον, ου, τό enýpnion substantivo neutro sonho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνύπνιον, ου, τό</td><td>substantivo neutro</td><td>sonho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enphoneo-bdag\" data-source=\"BDAG\" data-search=\"ἐνφωνέω enphōnéō verbo; variante textual forma textual de φωνέω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνφωνέω</td><td>verbo; variante textual</td><td>forma textual de φωνέω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enon-bdag\" data-source=\"BDAG\" data-search=\"ἐνών enṓn forma remissiva ver ἔνειμι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνών</td><td>forma remissiva</td><td>ver ἔνειμι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enopion-bdag\" data-source=\"BDAG\" data-search=\"ἐνώπιον enṓpion preposição com genitivo diante de; na presença de; à vista de; na opinião de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνώπιον</td><td>preposição com genitivo</td><td>diante de; na presença de; à vista de; na opinião de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enoristeron-bdag\" data-source=\"BDAG\" data-search=\"ἐνωρίστερον enōrísteron advérbio mais cedo; antecipadamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνωρίστερον</td><td>advérbio</td><td>mais cedo; antecipadamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enos-bdag\" data-source=\"BDAG\" data-search=\"Ἐνώς, ὁ Enṓs nome próprio masculino indeclinável Enos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἐνώς, ὁ</td><td>nome próprio masculino indeclinável</td><td>Enos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-henosis-bdag\" data-source=\"BDAG\" data-search=\"ἕνωσις, εως, ἡ hénōsis substantivo feminino união; unidade; concórdia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἕνωσις, εως, ἡ</td><td>substantivo feminino</td><td>união; unidade; concórdia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enotizomai-bdag\" data-source=\"BDAG\" data-search=\"ἐνωτίζομαι enōtízomai verbo; voz média escutar atentamente; dar ouvidos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνωτίζομαι</td><td>verbo; voz média</td><td>escutar atentamente; dar ouvidos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-henoch-bdag\" data-source=\"BDAG\" data-search=\"Ἑνώχ, ὁ Henṓch nome próprio masculino indeclinável Enoque BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἑνώχ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Enoque</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ex-bdag\" data-source=\"BDAG\" data-search=\"ἐξ ex preposição; forma remissiva ver ἐκ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξ</td><td>preposição; forma remissiva</td><td>ver ἐκ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hex-bdag\" data-source=\"BDAG\" data-search=\"ἕξ héx numeral cardinal indeclinável seis BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἕξ</td><td>numeral cardinal indeclinável</td><td>seis</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exaggello-bdag\" data-source=\"BDAG\" data-search=\"ἐξαγγέλλω exangéllō verbo proclamar; anunciar; relatar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξαγγέλλω</td><td>verbo</td><td>proclamar; anunciar; relatar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-entrope-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντροπή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entropḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἐντρέπω</span>; como em geral na literatura grega, empregado apenas metaforicamente.</p><p class=\"entry-text\">① <strong>Estado de quem está envergonhado: vergonha, humilhação</strong> (Diodoro Sículo 40, 5a; escólio a Apolônio de Rodes 3, 656–63a; Sl 34:26; 68:8, 20). <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἐντροπήν</span> <span class=\"greek\">τινι</span>, «para envergonhar alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6:5</a>; 15:34.</p><p class=\"entry-text\">② <strong>Deferência a alguém em reconhecimento de sua posição especial: respeito, consideração</strong> (Sófocles e outros; Políbio 4, 52, 2; Díon Crisóstomo 29 [46], 4; OGI 323, 7 [século II a.C.]; PGM 5, 17; Josefo, Ant. 2, 46; 14, 375). <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινι</span> <span class=\"greek\">ἀπονέμειν</span>, «prestar a alguém todo o respeito que lhe é devido», IMg 3:1. — B. 1141; M-M.</p></section></article>\n<article id=\"entry-entryphao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντρυφάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entrypháō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">De <span class=\"greek\">τρυφή</span>; futuro <span class=\"greek\">ἐντρυφήσω</span>; primeiro aoristo <span class=\"greek\">ἐνετρύφησα</span>, LXX; ver <span class=\"greek\">τρυφάω</span>; Eurípides e outros.</p><p class=\"entry-text\">① <strong>Experimentar deleite exuberante em algo: deleitar-se</strong>, com dativo <span class=\"greek\">τινί</span>. <span class=\"greek\">ἐντρύφα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῇ</span> (isto é, <span class=\"greek\">ἱλαρότητι</span>), «deleita-te nela», Hm 10, 3, 1.</p><p class=\"entry-text\">② <strong>Entregar-se ao comportamento autoindulgente: folgar, banquetear-se, divertir-se desenfreadamente</strong>; desenvolvimento do sentido 1 (Xenofonte, Hell. 4, 1, 30; Diodoro Sículo 19, 71, 3; LXX; Fílon, Spec. Leg. 3, 27; Taciano 12, 4). Construção <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «em algo» (Is 55:2: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγαθοῖς</span>; também Cássio Díon 65, 20). <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἀπάταις</span>, «deleitar-se em suas concupiscências», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:13</a> (variantes textuais: <span class=\"greek\">ἀγάπαις</span> e <span class=\"greek\">ἀγνοίαις</span>). — DELG, s.v. <span class=\"greek\">θρύπτω</span> III; M-M.</p></section></article>\n<article id=\"entry-entynchano-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντυγχάνω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entynchánō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro, segunda pessoa do plural, <span class=\"greek\">ἐντεύξεσθε</span> (Justino, A I, 45, 6); segundo aoristo <span class=\"greek\">ἐνέτυχον</span>; primeiro aoristo médio do subjuntivo <span class=\"greek\">ἐντεύξωμαι</span>, Hm 10, 2, 5 (cf. a forma simples, 2Mc 15:7). Sentidos diversos: «encontrar», «dirigir-se a», «aproximar-se», «apelar», «peticionar»; ver <span class=\"greek\">τυγχάνω</span>; Sófocles, Heródoto e outros.</p><p class=\"entry-text\">① <strong>Fazer um pedido insistente mediante contato com a pessoa a quem se recorre.</strong></p><p class=\"entry-text\">ⓐ <strong>Aproximar-se de alguém ou recorrer a alguém</strong>, com dativo <span class=\"greek\">τινί</span> (Políbio 4, 30, 1; Diodoro Sículo 19, 60, 1; OGI 664, 10; 669, 46; SIG 820, 13 [século I d.C.]; PTebt 58, 43; Dn 6:13 LXX; Josefo, Ant. 16, 170; Justino, D. 2, 6: <span class=\"greek\">τοῖς</span> <span class=\"greek\">Πλατωνικοῖς</span>): MPol 17:2. Com <span class=\"greek\">τινὶ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, «recorrer a alguém a respeito de algo» (Políbio 4, 76, 9; PSI 410, 14 [século III a.C.]: <span class=\"greek\">περὶ</span> <span class=\"greek\">Ὥρου</span> <span class=\"greek\">ἐντυχεῖν</span> <span class=\"greek\">Ἀμμωνίῳ</span>; PAmh 142, 10): <span class=\"greek\">περὶ</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἅπαν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλῆθος</span> <span class=\"greek\">ἐνέτυχόν</span> <span class=\"greek\">μοι</span>, «a respeito de quem todo o povo recorreu a mim», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:24</a> (En 22:7: <span class=\"greek\">Ἄβελ</span> <span class=\"greek\">ἐντυγχάνει</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτοῦ</span> [<span class=\"greek\">τοῦ</span> <span class=\"greek\">Κάϊν</span>]). A respeito de coisas: Josefo, Ant. 12, 18: <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">ἐντυγχάνειν</span> <span class=\"greek\">μέλλει</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">βασιλεῖ</span>; Plutarco, Alex. 692 [49, 4]: <span class=\"greek\">ὡς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἀναγκαίων</span> <span class=\"greek\">ἔχοντας</span> <span class=\"greek\">ἐντυχεῖν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μεγάλων</span>; Them. 125 [27, 2] (ver Field, Notes, pp. 140s.).</p><p class=\"entry-text\">Com <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span>, «interceder por alguém» (Eliano, VH 1, 21; PAmh 35, 20; PTebt 183 [século II a.C.]); quanto à intercessão do Espírito Santo, <span class=\"greek\">κατὰ</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἁγίων</span>, «interceder pelos santos segundo Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:27</a>. Quanto à intercessão de Cristo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:25</a>. Com <span class=\"greek\">τινὶ</span> <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>, «recorrer a alguém contra terceira pessoa» (cf. PGiss 36, 15 [161 a.C.]: <span class=\"greek\">ἐνετύχομεν</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὑμῶν</span>; PAmh 134, 10; 1Mc 8:32; 11:25; En 7:6: <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span> <span class=\"greek\">ἐνέτυχεν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνόμων</span>; TestJob 17:5: <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμῶν</span>): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11:2</a>; Hm 10, 2, 5. — D. Crump, Jesus the Intercessor, 1992.</p><p class=\"entry-text\">ⓑ Visto que as petições também são dirigidas a Deus, <span class=\"greek\">ἐ</span>. pode ser traduzido por <strong>orar</strong> (Máximo de Tiro 10, 1b: <span class=\"greek\">ἐντυχεῖν</span> <span class=\"greek\">θεοῖς</span>; BGU 246, 12 [cerca de 200 d.C.]: <span class=\"greek\">ἰδότες</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">νυκτὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ἐντυγχάνω</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ὑμῶν</span>; Sb 8:21; 16:28; En 9:3 e 10 e outras; Fílon, Mos. 1, 173). Com dativo da pessoa a quem se ora, <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> (com <span class=\"greek\">ἐξομολογεῖσθαι</span>), Hm 10, 3, 2; <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, «a Deus», Hs 2:6. Também <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span> (cf. Plutarco, Fab. 185 [20, 2]), Hs 2:8. Com <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, «por alguém»: 1 Cl 56:1; Pol 4:3.</p><p class=\"entry-text\">② Da ideia de «deparar-se com» ou «encontrar» um livro (Platão e outros) desenvolve-se o sentido <strong>ler</strong> (Políbio 1, 3, 10; Plutarco, Rom. 24 [12, 6]; Vettius Valens 358, 25; 2Mc 2:25; 15:39; Josefo, Ant. 1, 15; 12, 226; Justino, A I, 26, 8 e outros; Fílon, Spec. Leg. 4, 161, de um livro, <span class=\"greek\">ἐντυγχάνειν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀναγινώσκειν</span>, «ler e prestar atenção»): Dg 12:1. — R. Laqueur, Quaestiones Epigr., dissertação, Estrasburgo, 1904, pp. 15ss.; DELG, s.v. <span class=\"greek\">τυγχάνω</span>; M-M; TW; Spicq; Sv.</p></section></article>\n<article id=\"entry-entylisso-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντυλίσσω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entylíssō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐνετύλιξα</span>; particípio perfeito passivo <span class=\"greek\">ἐντετυλιγμένος</span> (Aristófanes, Plut. 692; Nub. 987; Epicteto 1, 6, 33; Ateneu 3, 69, 106e; PSI 1082, 16).</p><p class=\"entry-text\">① <strong>Envolver algo em torno de um objeto: envolver, enrolar.</strong> Com <span class=\"greek\">σῶμα</span> <span class=\"greek\">σινδόνι</span>, «um corpo em um lençol de linho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:53</a>; com <span class=\"greek\">ἐν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.59\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:59</a> (cf. PGM 7, 826: <span class=\"greek\">ἐντύλισσε</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">φύλλα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σουδαρίῳ</span>; contudo, o versículo de Mateus possui forte testemunho em favor do dativo simples).</p><p class=\"entry-text\">② <strong>Dobrar</strong>, com referência a um <span class=\"greek\">σουδάριον</span>, «lenço», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.7\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20:7</a>. — DELG, s.v. <span class=\"greek\">τύλη</span>; M-M.</p></section></article>\n<article id=\"entry-entypoo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντυπόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entypóō⟧</span><span class=\"separator\">·</span><span>verbo; voz passiva atestada</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Passivo: primeiro futuro, terceira pessoa do singular, <span class=\"greek\">ἐντυπωθήσεται</span>; particípio perfeito <span class=\"greek\">ἐντετυπωμένα</span> (Êx 36:37, códice A; TestSol). Ver <span class=\"greek\">τύπος</span>; Pseudo-Aristóteles, Mirabilia 155; De Mundo 6; Cássio Díon; Plutarco; Filóstrato, Vi. Apoll. 3, 42, p. 117, 13; Êx 36:37, variante textual; TestSol 13, 12 C; EpArist 67; Fílon, Leg. All. 3, 95: <span class=\"greek\">τῇ</span> <span class=\"greek\">ψυχῇ</span>; Josefo, Bell. 2, 120.</p><p class=\"entry-text\"><strong>Formar letras ou figuras por incisão: entalhar, gravar, imprimir.</strong> <span class=\"greek\">ἐν</span> <span class=\"greek\">γράμμασιν</span> <span class=\"greek\">ἐντετυπωμένη</span> <span class=\"greek\">λίθοις</span>, «gravada em letras sobre pedras», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3:7</a> (Ístro [século III a.C.], 334 Fgm. 53 Jac.: <span class=\"greek\">ἐντετύπωται</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λίθῳ</span> <span class=\"greek\">ἀνθρωποειδὴς</span> <span class=\"greek\">εἰκών</span>, «uma figura humana foi entalhada na pedra»). — DELG, s.v. <span class=\"greek\">τύπτω</span>; M-M.</p></section></article>\n<article id=\"entry-enybrizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνυβρίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enybrízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐνύβρισα</span> (ver <span class=\"greek\">ὑβρίζω</span>; Sófocles e outros; Políbio; Diodoro Sículo; Kaibel 195, 1; POxy 237 VI, 17; TestSol 4, 2 D; JosAs 23:4 [<span class=\"greek\">ἐνυβρίσθην</span>]; Josefo, Ant. 20, 117 e outros; Atenágoras [Ath.] 2, 2: <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span>; 24, 4: <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀρχῇ</span>).</p><p class=\"entry-text\"><strong>Insultar, ultrajar</strong>, com objeto <span class=\"greek\">τὶ</span> (Josefo, Ant. 1, 47: <span class=\"greek\">μου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γνώμην</span>, «a minha decisão», isto é, o mandamento de Deus). <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span>, «o Espírito», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:29</a>. — DELG, s.v. <span class=\"greek\">ὕβρις</span>; M-M; TW.</p></section></article>\n<article id=\"entry-enydros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔνυδρος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦énydros⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Desde Hesíodo, Fgm. 27, aplicado a coisas que contêm água; desde Sófocles, também a seres que vivem dentro da água ou à sua margem, como em Sb 19:10, 19; 4Mc 1:34; Hes. 19:3; Fílon; Josefo, Ant. 16, 142; Ar. 12, 3.</p><p class=\"entry-text\"><strong>Que vive na água, aquático.</strong> <span class=\"greek\">ζῷα</span> … <span class=\"greek\">ἔ</span>., «animais que vivem na água», Hm 12, 4, 1, variante textual. — DELG, s.v. <span class=\"greek\">ὕδωρ</span>.</p></section></article>\n<article id=\"entry-enypniazomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνυπνιάζομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enypniázomai⟧</span><span class=\"separator\">·</span><span>verbo; depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ὕπνος</span>; primeiro futuro <span class=\"greek\">ἐνυπνιασθήσομαι</span>; primeiro aoristo <span class=\"greek\">ἐνυπνιάσθην</span>, Gn 28:12 e outras ocorrências, e <span class=\"greek\">ἠνυπνιάσθην</span>, Dn (Teodocião) 2:3; primeiro aoristo médio <span class=\"greek\">ἠνυπνιασάμην</span>, Jr 23:25 (como depoente em Hipócrates e outros; Plutarco, Brut. 995 [24, 3]; João Lido, De Ostentis, p. 76, 21; Fílon, Somn. 2, 105; e sempre assim no Antigo e no Novo Testamento).</p><p class=\"entry-text\"><strong>Sonhar.</strong> <span class=\"greek\">ἐνυπνίοις</span> <span class=\"greek\">ἐ</span>., «ter visões em sonhos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:17</a> (Jl 3:1). Referindo-se a pessoas facciosas: <span class=\"greek\">ἐνυπνιαζόμενοι</span>, Jd 8. — M-M; TW.</p></section></article>\n<article id=\"entry-enypnion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνύπνιον, ου, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enýpnion⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver a entrada precedente; Píndaro, Ésquilo, Heródoto e outros; Arriano, Alex. An. 2, 18, 1; inscrições, papiros, LXX, En; PsSol 6:3; Fílon; Josefo, C. Ap. 1, 207, 211; Test12Patr.</p><p class=\"entry-text\"><strong>Sonho</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:17</a> (Jl 3:1). — B. 269; DELG, s.v. <span class=\"greek\">ὕπνος</span>; M-M; TW.</p></section></article>\n<article id=\"entry-enphoneo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνφωνέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enphōnéō⟧</span><span class=\"separator\">·</span><span>verbo; variante textual</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Não encontrado em nenhum outro lugar. Ocorre em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:24</a>, códice D (Tischendorf, aparato crítico, para <span class=\"greek\">φωνέω</span>). Ver também <span class=\"greek\">ἐκφωνέω</span>.</p></section></article>\n<article id=\"entry-enon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνών</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enṓn⟧</span><span class=\"separator\">·</span><span>forma remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἔνειμι</span>.</p></section></article>\n<article id=\"entry-enopion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνώπιον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enṓpion⟧</span><span class=\"separator\">·</span><span>preposição com genitivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Propriamente neutro de <span class=\"greek\">ἐνώπιος</span>, funcionando como preposição (ver observação no início de <span class=\"greek\">ἀνά</span>) com genitivo: SIG² 843, 7 [Trajano]: <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προγεγραμμένων</span> <span class=\"greek\">θεῶν</span>; cf. Plutarco, Mor. 274b, 3; PCairZen 73, 14 [257 a.C.]; PLond II, 35, 6, p. 25 [161 a.C., reconstruído]; PGrenf I 38, 11; POxy 658, 9; LXX; pseudoepígrafos; Justino, A I, 50, 5 [em lugar de <span class=\"greek\">ἐνάντιον</span>, Is 53:12, assim também em quatro outras citações da LXX]. Ocorre especialmente em Lucas (22 vezes), Atos (13 vezes) e Apocalipse (32 vezes); nove vezes em 1 Clemente; uma vez em cada um dos livros João, 1 João, 3 João, Tiago e 1 Pedro; nenhuma em Mateus, Marcos, 2 Pedro, 2 João ou Judas.</p><p class=\"entry-text\">① <strong>Referente à posição à frente de uma entidade: diante de alguém ou de algo.</strong> <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 7:15</a>; em geral, é necessário subentender <span class=\"greek\">εἶναι</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:4</a>; 4:5s.; 8:3; 9:13. Depois de verbos como «estar de pé», «colocar», «aproximar-se» etc. (escólio a Apolônio de Rodes 4, 1043b, a respeito de suplicantes: <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">ἱστάμενοι</span>): <span class=\"greek\">στῆναι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:30</a>; GJs 11:2; <span class=\"greek\">ἑστηκέναι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 7:9</a>; 8:2 (R. Charles, ICC, Apocalipse, ad loc.: «estar a serviço de, servir perante»); 11:4; 12:4; 20:12; <span class=\"greek\">παρεστηκέναι</span> (cf. 3Rs 12:6; Jz 20:28), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:10</a>; <span class=\"greek\">ἱστάναι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 6:6</a>; <span class=\"greek\">καθῆσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:16</a>. <span class=\"greek\">θύρα</span> <span class=\"greek\">ἠνεῳγμένη</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινος</span>, «porta que permanece aberta diante de alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:8</a>.</p><p class=\"entry-text\">Após verbos de movimento: <span class=\"greek\">τιθέναι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:18</a>; <span class=\"greek\">βάλλειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4:10</a>; <span class=\"greek\">ἀναβαίνειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 8:4</a>; <span class=\"greek\">πίπτειν</span>, para adoradores ou admiradores que se prostram diante de alguém (1Rs 25:23), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4:10</a>; 5:8; cf. 7:11; <span class=\"greek\">προσκυνεῖν</span> (Sl 21:28; cf. v. 30), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:9</a>; 15:4 (cf. 22:8; quanto a esse hebraísmo, ver <span class=\"greek\">προσκυνέω</span>, a). A respeito de um precursor ou arauto: depois de <span class=\"greek\">προέρχεσθαι</span> (cf. 2Cr 1:10; 1Rs 12:2ab), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:17</a>; <span class=\"greek\">προπορεύεσθαι</span>, v. 76. <span class=\"greek\">σκάνδαλα</span> <span class=\"greek\">βάλλειν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:14</a>.</p><p class=\"entry-text\">② <strong>Referente a estar presente ou visível: à vista de, na presença de, entre.</strong></p><p class=\"entry-text\">ⓐ <strong>Literalmente.</strong> <span class=\"greek\">φαγεῖν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:43</a>; 13:26 (cf. 2Rs 11:13; 3Rs 1:25). <span class=\"greek\">σημεῖα</span> <span class=\"greek\">ποιεῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.30\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20:30</a>. <span class=\"greek\">ἀνακρίνειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:14</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:25</a>; 8:47; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:9</a>, 19; 27:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13:13</a>; 14:3, 10; 3Jo 6; <span class=\"greek\">ἐ</span>. <span class=\"greek\">πολλῶν</span> <span class=\"greek\">μαρτύρων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6:12</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">πάντων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5:20</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:53</a>, códice D; <span class=\"greek\">βαπτισθῆναι</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">αὐτοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:7</a>, códice D (ver 4b abaixo); <span class=\"greek\">χορεύσασα</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγγέλων</span>, GJs 15:3.</p><p class=\"entry-text\">ⓑ <strong>Não literalmente.</strong> <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πάρεσμεν</span>, «estamos presentes diante de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:33</a>. Também depois de verbos de movimento: <span class=\"greek\">βαστάζειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἐθνῶν</span>, «levar o nome perante as nações», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:15</a>. Depois de <span class=\"greek\">ἀρνεῖσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:9</a>; <span class=\"greek\">ὁμολογεῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:5</a>; 2 Cl 3:2 (<span class=\"greek\">ἔμπροσθεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:32</a>); <span class=\"greek\">κατηγορεῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12:10</a>; <span class=\"greek\">καυχᾶσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:29</a>; <span class=\"greek\">δικαιοῦν</span> <span class=\"greek\">ἑαυτόν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:15</a>. <span class=\"greek\">πίστιν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σεαυτὸν</span> <span class=\"greek\">ἔχε</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «conserva para ti mesmo a tua convicção diante de Deus», isto é, «entre ti e Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14:22</a> (ver <span class=\"greek\">πίστις</span> 2d<span class=\"greek\">ε</span>); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4:2</a>; MPol 14:1s.</p><p class=\"entry-text\">É ainda expressão predileta de afirmações e juramentos que invocam a Deus como aquele que tudo vê: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5:21</a>; 6:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2:14</a>; 4:1. Traduções como <strong>«entre», «diante de» e «na presença de»</strong> também são apropriadas para os exemplos seguintes: <span class=\"greek\">γίνεται</span> <span class=\"greek\">χαρὰ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγγέλων</span>, «há alegria entre os anjos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:10</a>. <span class=\"greek\">ἔσται</span> <span class=\"greek\">σοι</span> <span class=\"greek\">δόξα</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">πάντων</span>, «terás honra diante de todos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:10</a>. <span class=\"greek\">εὑρίσκειν</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «encontrar favor diante de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.46\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:46</a> (cf. Gn 6:8, variante textual [A. Rahlfs, Genesis, 1926, p. 61] e outras). <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">δεσπότου</span>, «diante do Senhor de todos», GJs 11:2. <span class=\"greek\">προορώμην</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κύριον</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">μου</span>, «eu via o Senhor diante de mim», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:25</a> (Sl 15:8).</p><p class=\"entry-text\">Depois de verbos de recordar e esquecer: <span class=\"greek\">μνησθῆναι</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.31\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16:19</a>. <span class=\"greek\">ἐπιλελησμένον</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:6</a> (cf. <span class=\"greek\">ἐρωτηθῆναι</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἁγίας</span> <span class=\"greek\">δόξης</span> <span class=\"greek\">σου</span>, TestAbr B 4, p. 108, 22 [Stone, p. 64]). Para o dativus auctoris: <span class=\"greek\">εἰσηκούσθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">δέησις</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">κυρίου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «a tua súplica foi ouvida pelo Senhor Deus», GJs 20:3 (cf. PsSol 1:2; GrBar 1:5).</p><p class=\"entry-text\">③ <strong>Referente à exposição ao juízo de valor: na opinião de, segundo o julgamento de.</strong> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἑαυτῶν</span>, B 4:11 (Is 5:21); <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀνθρώπων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 8:21b</a>; Pol 6:1 (cf. Pv 3:4). Como regra (também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 8:21a</a>), emprega-se a respeito de <span class=\"greek\">θεός</span> ou <span class=\"greek\">κύριος</span>; assim, depois de <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀρεστά</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3:22</a>; <span class=\"greek\">βδέλυγμα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:15</a>; <span class=\"greek\">δίκαιος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:6</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:19</a>; <span class=\"greek\">δικαιοσύνη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.75\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:75</a>; <span class=\"greek\">δικαιοῦσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3:20</a>; <span class=\"greek\">εὐάρεστος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:21</a>; 1 Cl 21:1; 60:2 (cf. Dt 13:19); <span class=\"greek\">καλός</span>, <span class=\"greek\">ἀπόδεκτος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 2:3</a>; 5:4; <span class=\"greek\">μέγας</span> (4Rs 5:1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:15</a>; <span class=\"greek\">πολυτελής</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:4</a>; <span class=\"greek\">πεπληρωμένος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:2</a>.</p><p class=\"entry-text\">As construções com <span class=\"greek\">ἀρεστός</span> e <span class=\"greek\">εὐάρεστος</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινος</span>, já citadas, fazem a transição para construções em que <span class=\"greek\">ἐ</span>. com genitivo simplesmente equivale ao dativo: <span class=\"greek\">ἤρεσεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">παντὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πλήθους</span>, «a proposta agradou a toda a multidão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 6:5</a> (cf. Dt 1:23, variante textual; 2Rs 3:36). <span class=\"greek\">φανεροῦσθαι</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 7:12</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:13</a>. Provavelmente também pertence aqui <span class=\"greek\">ἡ</span> <span class=\"greek\">ἁμαρτία</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἐστίν</span>, «meu pecado está diante de mim», 1 Cl 18:3 (Sl 50:5), e <span class=\"greek\">ταπεινώθητε</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">κυρίου</span>, «humilhai-vos diante do Senhor», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4:10</a>.</p><p class=\"entry-text\">④ <strong>Usos especiais.</strong></p><p class=\"entry-text\">ⓐ Em relação a <span class=\"greek\">ἁμαρτάνειν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινος</span>: <strong>pecar contra alguém</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:18</a>, 21 (cf. Jdt 5:17; 1Rs 7:6; 20:1).</p><p class=\"entry-text\">ⓑ <strong>Pela autoridade de; em nome de</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13:12</a>, 14; 19:20. Também simplesmente <strong>por</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:7</a>, códice D (mas ver 2a). — Johannessohn, Präpositionen, pp. 194–197; 359–361; A. Wikenhauser, «<span class=\"greek\">Ἐνώπιος</span> — <span class=\"greek\">ἐνώπιον</span> — <span class=\"greek\">κατενώπιον</span>», BZ 8, 1910, pp. 263–270; DELG, s.v. <span class=\"greek\">ἐνῶπα</span>; M-M.</p></section></article>\n<article id=\"entry-enoristeron-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνωρίστερον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enōrísteron⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Advérbio de <span class=\"greek\">ἔνωρος</span> (Filarco, 81 Fgm. 44 Jac.). <strong>Mais cedo; antes do tempo</strong>, AcPl Ha 3, 4. — DELG, s.v. <span class=\"greek\">ὥρα</span>.</p></section></article>\n<article id=\"entry-enos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐνώς, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Enṓs⟧</span><span class=\"separator\">·</span><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Nome indeclinável (hebraico א<span class=\"greek\">ֱ</span>נו<span class=\"greek\">ֹ</span>ש<span class=\"greek\">ׁ</span>). <strong>Enos</strong>, filho de Sete (Gn 4:26; Fílon, Det. Pot. Ins. 138s.; em Josefo, Ant. 1, 79, 83, <span class=\"greek\">Ἄνωσος</span> [variante textual: <span class=\"greek\">Ἔνωσος</span>], <span class=\"greek\">ου</span>). Na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:38</a>. — BHHW I, p. 413.</p></section></article>\n<article id=\"entry-henosis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕνωσις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hénōsis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Pré-socráticos e outros; Aristóteles, Phys. 222a, 20; Marco Aurélio 6, 38; Herm. Wr. 1, 6; 14, 6 e outros; Fílon, Leg. All. 1, 8; Ar. 13, 5; Ath.</p><p class=\"entry-text\"><strong>Qualidade ou estado de plena concordância (em contraste com discórdia ou dissensão): união, unidade.</strong> IMg 13:2; ITr 11:2. <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνεύματος</span>, «de carne e espírito», IMg 1:2. <span class=\"greek\">ἕ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἵματος</span>, «unidade em seu sangue» (admite mais de uma interpretação, mas o essencial é a ideia de união por meio do único sangue), IPhld 4. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἀγαπᾶν</span>, «amar a unidade», IPhld 7:2. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἑ</span>. <span class=\"greek\">φροντίζειν</span>, «empenhar-se pela unidade», IPol 1:2. <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">κατηρτισμένος</span>, «homem com propósitos de unidade», IPhld 8:1. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">ποιεῖσθαι</span>, «entrar em união» (no casamento), IPol 5:2. — Th. Preiss, «La mystique de l’imitation du Christ et de l’unité chez Ign. d’Ant.», RHPR 18, 1938, pp. 197–241; DELG, s.v. <span class=\"greek\">εἷς</span>; M-M; Sv.</p></section></article>\n<article id=\"entry-enotizomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνωτίζομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enōtízomai⟧</span><span class=\"separator\">·</span><span>verbo; voz média</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐνωτισάμην</span>, LXX; segunda pessoa do plural <span class=\"greek\">ἠνωτίσασθε</span>, Jr 44:8.</p><p class=\"entry-text\"><strong>Escutar cuidadosamente o que se diz: dar ouvidos, prestar atenção a.</strong> Ver <span class=\"greek\">οὖς</span> 2; Hesíquio; Ducas 84, 19, I. Bekker [1834]. Com acusativo <span class=\"greek\">τὶ</span>, «algo» (Syntipas, p. 12, 6 e outros; Pselo, p. 77, 6; Gn 4:23; Jó 33:1; TestReub 1:5; TestIss 1:1): <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span>, «as palavras», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:14</a> (cf. Sl 5:2). Em uso absoluto: B 9:3 (Is 1:2). — Sobre a forma, ver B-D-F § 123, 2; M-M; TW.</p></section></article>\n<article id=\"entry-henoch-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑνώχ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Henṓch⟧</span><span class=\"separator\">·</span><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Algumas edições apresentam <span class=\"greek\">Ἐνώχ</span>; indeclinável (hebraico ח<span class=\"greek\">ֲ</span>נו<span class=\"greek\">ֹ</span>ך<span class=\"greek\">ְ</span>). Atestado na LXX; En; ApcEl [PSI I, 7, verso, 4, texto reconstruído]; TestAbr B; ApcEsdr 5:2, p. 30, 23 Tdf.; Fílon; Test12Patr; Justino, D. 23, 1 e outros. Em Josefo, Ant. 1, 79, 85; 9, 28, lê-se <span class=\"greek\">Ἄνωχος</span> [variante: <span class=\"greek\">Ἔνωχος</span>], <span class=\"greek\">ου</span>.</p><p class=\"entry-text\"><strong>Enoque</strong>, filho de Jarede e pai de Matusalém (Gn 5:18ss.). Na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:37</a>. Como exemplo de fé e obediência a Deus e, consequentemente, trasladado ao céu (Gn 5:22, 24; Sir 44:16; Josefo, Ant. 1, 85): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:5</a>; 1 Cl 9:3. Palavra profética de Enoque: Jd 14s. (= En 1:9). Nesse texto, ele é chamado <span class=\"greek\">ἕβδομος</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἀδάμ</span>, «sétimo desde Adão» (cf. Diógenes Laércio 3, 1: Platão é <span class=\"greek\">ἕκτος</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Σόλωνος</span>, «sexto desde Sólon» na linha de seus descendentes; Ateneu 13, 555d, sobre Aristides, sogro de Sócrates: <span class=\"greek\">οὐ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δικαίου</span> <span class=\"greek\">καλουμένου</span> … <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τρίτου</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἐκείνου</span>).</p><p class=\"entry-text\">A citação de Enoque em B 4:3 não pode ser identificada com certeza. Enoque é introduzido por conjectura em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:19</a> (<span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">καί</span>; seguindo outros autores, F. Spitta, 1890, e J. Harris, Exp., 6.ª série, 4, 1901, pp. 346–349; 5, 1902, pp. 317–320; Moffatt; assim Goodsp., Probs., pp. 195–198; JBL 73, 1954, pp. 91s.; contra essa interpretação, E. Selwyn, 1 Pt, 1946, pp. 197s.). — P. Katz, Gnomon 26, 1954, p. 226; H. Jansen, D. Hen. gestalt. E. vergleich. rel. gesch. Untersuchung, 1939; RAC V, pp. 461–476; BHHW II, p. 692; TW.</p></section></article>\n<article id=\"entry-ex-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ex⟧</span><span class=\"separator\">·</span><span>preposição; forma remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Preposição. Ver <span class=\"greek\">ἐκ</span>.</p></section></article>\n<article id=\"entry-hex-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕξ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦héx⟧</span><span class=\"separator\">·</span><span>numeral cardinal indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Indeclinável (Homero e outros; papiros; LXX; pseudoepígrafos; Fílon; Josefo; Justino, D. 132, 1; Mel., HE 4, 26, 4).</p><p class=\"entry-text\"><strong>Seis.</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:25</a>; 13:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2:6</a>, 20 e outros. <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἓξ</span> <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πάσχα</span>, «seis dias antes da Páscoa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:1</a>. — MPol 9:3; Hv 3, 2, 5; DELG; M-M.</p></section></article>\n<article id=\"entry-exaggello-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξαγγέλλω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exangéllō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐξαγγελῶ</span>, LXX; primeiro aoristo <span class=\"greek\">ἐξήγγειλα</span>; terceira pessoa do singular do aoristo passivo <span class=\"greek\">ἐξηγγέλθη</span> (Justino, D. 75, 1). Ver <span class=\"greek\">ἀγγέλλω</span>; Homero e outros; Fílon; Josefo, Vi. 357 e outros.</p><p class=\"entry-text\"><strong>Proclamar, relatar, anunciar</strong> (assim na tragédia grega e em Heródoto e autores posteriores; inscrições [OGI 266, 34, ver nota]; PGM 5, 294; LXX; Fílon, Plant. 128; Josefo; TestJos 5:2, 3; Justino); no final breve de Marcos. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀρετάς</span>, «as virtudes», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:9</a>. — M-M; TW.</p></section></article>"};
